SELECT TABLE_SCHEMA, TABLE_NAME, TABLE_TYPE
FROM INFORMATION_SCHEMA.TABLES
ORDER BY TABLE_SCHEMA, TABLE_NAME;

DECLARE @RetryCount INT = 0;
DECLARE @MaxRetries INT = 5;
DECLARE @Success BIT = 0;

WHILE @RetryCount < @MaxRetries AND @Success = 0
BEGIN
    BEGIN TRY
        BEGIN TRANSACTION;

        -- === Place your transactional work here ===
        -- Example:
        -- UPDATE dbo.Products SET UnitPrice = UnitPrice * 1.10 WHERE ProductID = 1;

        COMMIT TRANSACTION;
        SET @Success = 1;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;

        IF ERROR_NUMBER() = 1205 -- Deadlock victim
        BEGIN
            SET @RetryCount = @RetryCount + 1;

            IF @RetryCount < @MaxRetries
            BEGIN
                WAITFOR DELAY '00:00:02'; -- Wait 2 seconds before retrying
            END
            ELSE
            BEGIN
                RAISERROR('Deadlock retry limit reached after %d attempts.', 16, 1, @MaxRetries);
            END
        END
        ELSE
        BEGIN
            -- Re-throw non-deadlock errors immediately
            DECLARE @ErrorMessage NVARCHAR(4000) = ERROR_MESSAGE();
            DECLARE @ErrorSeverity INT = ERROR_SEVERITY();
            DECLARE @ErrorState INT = ERROR_STATE();
            RAISERROR(@ErrorMessage, @ErrorSeverity, @ErrorState);
            SET @Success = 1; -- Exit the loop for non-deadlock errors
        END
    END CATCH
END;

